    public bool IsNotZero() => !IsZero();
    public bool IsAboveZero() => _si > 0;
    public bool IsBelowZero() => _si < 0;
    /// <summary>Not NaN and not infinite, like EngineeringUnits.</summary>
    public bool HasValue() => !double.IsNaN(_si) && !double.IsInfinity(_si);
    public bool HasNoValue() => !HasValue();
    /// <summary>A Density is never null - returns itself. The Density? version returns Zero for null.</summary>
    public Density IfNullSetToZero() => this;
    public static Density Min(Density a, Density b) => a._si <= b._si ? a : b;
    public static Density Max(Density a, Density b) => a._si >= b._si ? a : b;
    /// <summary>
    /// == is an exact double comparison, so 1 ft == 12 in can be false after rounding. Use this when the values
    /// come from different units. EngineeringUnits compares exactly (fractions) and needs no tolerance.
    /// </summary>
    public bool IsCloseTo(Density other, double relativeTolerance = 1e-12)
        => _si == other._si || Math.Abs(_si - other._si) <= relativeTolerance * Math.Max(Math.Abs(_si), Math.Abs(other._si));
    public bool IsNaN() => double.IsNaN(_si);
    public bool IsInfinity() => double.IsInfinity(_si);

    // ---- Equality ----
    public bool Equals(Density other) => _si.Equals(other._si);
    public override bool Equals(object? obj) => obj is Density other && Equals(other);
    public override int GetHashCode() => _si.GetHashCode();
    public int CompareTo(Density other) => _si.CompareTo(other._si);
    public int CompareTo(object? obj) => obj is Density other ? CompareTo(other) : throw new ArgumentException($"Can't compare Density with {obj?.GetType().Name ?? "null"}");

    // ---- Text ----
    /// <summary>SI value with 4 significant digits, e.g. "1.5 kW" is printed as "1500 W".</summary>
    public override string ToString() => ToString(null, null);
    public string ToString(IFormatProvider formatProvider) => ToString(null, formatProvider);
    public string ToString(string? format) => ToString(format, null);
    public string ToString(string? format, IFormatProvider? formatProvider) => QuantityFormatter.Format(_si, DensityUnit.SI.Symbol, format, formatProvider);
    /// <summary>The value in <paramref name="unit"/>, e.g. "1.5 kW".</summary>
    public string ToString(DensityUnit unit, string? format = null, IFormatProvider? formatProvider = null) => QuantityFormatter.Format(As(unit), unit.Symbol, format, formatProvider);

    /// <summary>
    /// The same value, shown in <paramref name="unit"/>: <c>$"{p.ToUnit(PressureUnit.Bar)}"</c> prints "2 bar". Values are always
    /// stored in SI, so this is a display wrapper - it converts back to Density, but math on it needs the Density first.
    /// </summary>
    public QuantityInUnit<Density> ToUnit(DensityUnit unit) => new(this, unit);

    /// <summary>The value in SI. (A decimal in EngineeringUnits; the same number as <see cref="SI"/> here.)</summary>
    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public double AsSI => _si;

    /// <summary>Returns the same value: it is always stored in SI. (EngineeringUnits converts the unit here.)</summary>
    public Density ConvertToSI() => this;

}

/// <summary>Writes {"Value": si, "Unit": "kg/m³"}. Reads that (any unit of Density, by exact symbol) or a bare SI number - a unit of another quantity is rejected.</summary>
public sealed class DensityJsonConverter : JsonConverter<Density>
{
    public override Density Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        => Density.FromSI(QuantityJson.Read(ref reader, "Density", DensityUnit.BySymbol));

    public override void Write(Utf8JsonWriter writer, Density value, JsonSerializerOptions options)
        => QuantityJson.Write(writer, value.SI, DensityUnit.SI.Symbol);
}

public static partial class UnitMath
{
    [return: DimensionOf(nameof(value), PowerParameter = nameof(toPower))]
    public static UnknownUnit Pow(this Density value, int toPower) => new(Math.Pow(value.SI, toPower));

    [return: DimensionOf(nameof(value), Root = 2)]
    public static UnknownUnit Sqrt(this Density value) => new(Math.Sqrt(value.SI));

    public static Density Sum(this IEnumerable<Density> values)
    {
        double sum = 0;
        foreach (var v in values) sum += v.SI;
        return Density.FromSI(sum);
    }

    public static Density Average(this IEnumerable<Density> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : Density.FromSI(sum / count);
    }

    public static Density Min(this IEnumerable<Density> values) => Aggregate(values, Math.Min);
    public static Density Max(this IEnumerable<Density> values) => Aggregate(values, Math.Max);

    private static Density Aggregate(IEnumerable<Density> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return Density.FromSI(result);
    }
}
